#!/usr/bin/env python3
"""Generates Tests/Compiler/Srm23ExpStmt.lean: expected statements (fully qualified) of the SRM23 theorems, from the Lean text of
scripts/srm23/EXPECTED.txt (fixed before any proof file) with M/Q substitution, plus wrong-expected mutations.  usage: python3 -I scripts/srm23/gen_exp.py"""
HEAD = '''import Tests.Compiler.Srm22PairsTest
import Tools.ShippingSrm23Regs
set_option autoImplicit false
-- GENERATED by scripts/srm23/gen_exp.py from scripts/srm23/EXPECTED.txt; do not edit.
namespace Tests.Compiler.Srm23ExpStmt
open Sparkle.IR.AST Sparkle.IR.OptCheck Sparkle.IR.HierCheck
'''
CTX = '''∀ {{mctx : Lean.Meta.Context}} {{mref : ST.Ref IO.RealWorld Lean.Meta.State}} {{cctx : Lean.Core.Context}} {{cref : ST.Ref IO.RealWorld Lean.Core.State}}
    {{w w1 : Void IO.RealWorld}} {{b raw : Module}} {{D : Design}}
    (hcore : Tools.ShippingEntrySoundness.RunsTo (Sparkle.Compiler.Elab.synthesizeCombinationalCore `Tests.Compiler.SharedLeafMemKidTest.{P} [] false) mctx mref cctx cref w (raw, D) w1)
    (hpost : b = Sparkle.IR.ZeroWidth.dropZeroWidthModule raw ∨ b = Sparkle.IR.RefineCheck.mergeChecked (Sparkle.IR.ZeroWidth.dropZeroWidthModule raw))
    (entry : Tools.ShippingMachineEntry.MachineDefines mctx mref cctx cref `Tests.Compiler.SharedLeafMemKidTest.{P} Tests.Compiler.SharedLeafMemKidTest.{P}.machineData.shape)
    (hBnd : Tests.Compiler.Srm9ComposedTest.{BND} mctx mref cctx cref w raw D)'''
GAP = 'Tools.ShippingSrm22Width.ShippedRegsFromSource b'
BODY = {
 'hierGate': ' Sparkle.IR.RefineCheck.hierGate b = true',
 'shippedRegsFromSource': ' ' + GAP,
 'hstX_of_hst3': '''
    (hnd : (b.wires.map (·.name)).Nodup)
    (hsI : ∀ p ∈ b.inputs, Sparkle.Backend.Verilog.sanitizeName p.name = p.name)
    (C : String → Option (Module × Sparkle.IR.Semantics.WEnv)) (st0 : String → Nat),
    Tools.ShippingSrm13Supply.NonRegBounded (checkedOptimize b) st0 →
      ∀ x ∈ (openIns b).map (·.name), x ∉ Tools.ShippingHierOpen.bodyInstOuts C b.body → st0 x < 2 ^ Sparkle.IR.RegDedup.declWidth b x''',
 'regsFit_of_hstR_hst1': '''
    (st0 : String → Nat) (hW : Tools.ShippingSrm22Width.ShippedRegWidthLe b),
    Tools.ShippingSrm13Supply.RegsAtInit (checkedOptimize b) st0 →
      (∀ r ∈ seqRegs (openFlat b (openIns b) (openOuts b)), st0 r.1 < 2 ^ Sparkle.IR.RegDedup.declWidth b r.1) →
      Tools.ShippingSrm13Supply.RegsFit (checkedOptimize b)''',
}
out = [HEAD]
out.append('''def Exp_generic : Prop := ∀ {b : Module} (hgate : Sparkle.IR.RefineCheck.hierGate b = true), Tools.ShippingSrm22Width.ShippedRegsFromSource b\n''')
for X, BND in (('M', 'TmBnd'), ('Q', 'TqBnd')):
    P = 'topshare' + X
    ctx = CTX.format(P=P, BND=BND)
    for k, body in BODY.items():
        sep = ',' if k in ('hstX_of_hst3', 'regsFit_of_hstR_hst1') else ','
        if k in ('hierGate', 'shippedRegsFromSource'):
            out.append(f'def Exp_{X}_{k} : Prop :=\n  {ctx},{body}\n')
        else:
            out.append(f'def Exp_{X}_{k} : Prop :=\n  {ctx}\n   {body.lstrip(chr(10)).replace(chr(10)+"    (", chr(10)+"    (",1)}\n')
# mutations (wrong expected forms, must be REJECTED): gap binder kept; hW dropped; hpost dropped; the gap claim reversed (SourceRegsKept)
ctxM = CTX.format(P='topshareM', BND='TmBnd')
out.append(f'def Exp_mut_gapKept : Prop :=\n  {ctxM}\n    (hreg : {GAP}) (hnd : (b.wires.map (·.name)).Nodup)\n    (hsI : ∀ p ∈ b.inputs, Sparkle.Backend.Verilog.sanitizeName p.name = p.name)\n    (C : String → Option (Module × Sparkle.IR.Semantics.WEnv)) (st0 : String → Nat),\n    Tools.ShippingSrm13Supply.NonRegBounded (checkedOptimize b) st0 →\n      ∀ x ∈ (openIns b).map (·.name), x ∉ Tools.ShippingHierOpen.bodyInstOuts C b.body → st0 x < 2 ^ Sparkle.IR.RegDedup.declWidth b x\n')
out.append(f'def Exp_mut_wrongGap : Prop :=\n  {ctxM},\n   Tools.ShippingSrm22Width.SourceRegsKept b\n')
out.append(f'def Exp_mut_noHW : Prop :=\n  {ctxM}\n    (st0 : String → Nat),\n    Tools.ShippingSrm13Supply.RegsAtInit (checkedOptimize b) st0 →\n      (∀ r ∈ seqRegs (openFlat b (openIns b) (openOuts b)), st0 r.1 < 2 ^ Sparkle.IR.RegDedup.declWidth b r.1) →\n      Tools.ShippingSrm13Supply.RegsFit (checkedOptimize b)\n')
ctxNoPost = ctxM.replace('    (hpost : b = Sparkle.IR.ZeroWidth.dropZeroWidthModule raw ∨ b = Sparkle.IR.RefineCheck.mergeChecked (Sparkle.IR.ZeroWidth.dropZeroWidthModule raw))\n', '')
out.append(f'def Exp_mut_noHpost : Prop :=\n  {ctxNoPost},\n   {GAP}\n')
out.append('end Tests.Compiler.Srm23ExpStmt\n')
open('Tests/Compiler/Srm23ExpStmt.lean', 'w').write('\n'.join(out))
